"""Parsing and formatting for CREATE TABLE definitions."""

import re
from dataclasses import dataclass, field
from typing import List, Optional, Tuple

from sqlfmt.line import Line


@dataclass
class DdlColumn:
    name: str
    type_name: str
    has_inline_constraint: bool = False

    def __str__(self) -> str:
        return f"{self.name} {self.type_name}" + (
            " <+constraint>" if self.has_inline_constraint else ""
        )


@dataclass
class DdlTableConstraint:
    keyword: str

    def __post_init__(self) -> None:
        self.keyword = self.keyword.lower()


@dataclass
class DdlTable:
    table_name: str
    columns: List[DdlColumn]
    table_constraints: List[DdlTableConstraint] = field(default_factory=list)

    @property
    def column_count(self) -> int:
        return len(self.columns)

    @property
    def constraint_count(self) -> int:
        return len(self.table_constraints)

    @property
    def constrained_columns(self) -> List[DdlColumn]:
        return [column for column in self.columns if column.has_inline_constraint]

    @property
    def unconstrained_columns(self) -> List[DdlColumn]:
        return [column for column in self.columns if not column.has_inline_constraint]


_TOKEN = re.compile(
    r"\s+|--[^\n]*|/\*[\s\S]*?\*/|(?:[rRbBxX])?'(?:''|\\.|[^'])*'|"
    r'"(?:""|\\.|[^"])*"|`(?:``|\\.|[^`])*`|'
    r"[\w$]+|::|<=|>=|<>|!=|=>|[-+*/%=<>]|[^\s]"
)
_HEADER = re.compile(
    r'\s*create\s+table\s+(?:if\s+not\s+exists\s+)?'
    r'((?:[\w$]+|"(?:""|[^"])*"|`[^`]*`)(?:\s*\.\s*'
    r'(?:[\w$]+|"(?:""|[^"])*"|`[^`]*`))*)\s*\(', re.I
)
_CONSTRAINT = re.compile(r"^(primary\s+key|foreign\s+key|unique|check|constraint)\b", re.I)
_INLINE = re.compile(r"^(?:not\s+null|null|default|references|constraint|check)\b", re.I)


def _parts(source: str) -> Optional[Tuple[str, str, List[str], str]]:
    match = _HEADER.match(source)
    if not match:
        return None
    start = match.end()
    stack = ["("]
    item_start = start
    items = []
    pairs = {")": "(", "]": "[", ">": "<"}
    for token in _TOKEN.finditer(source, start):
        text = token.group()
        if text.isspace() or text.startswith(("'", '"', "`", "--", "/*")):
            continue
        if text in ("(", "["):
            stack.append(text)
        elif text == "<":
            # Angle brackets are type delimiters only after a type constructor.
            before = source[: token.start()].rstrip()
            if re.search(r"\b(?:array|struct|map|table)\s*$", before, re.I):
                stack.append(text)
        elif text in pairs and stack and stack[-1] == pairs[text]:
            stack.pop()
            if not stack:
                items.append(source[item_start:token.start()].strip())
                return match.group(0), match.group(1), items, source[token.end():]
        elif text == "," and len(stack) == 1:
            items.append(source[item_start:token.start()].strip())
            item_start = token.end()
    return None


def _column(item: str) -> Optional[DdlColumn]:
    tokens = [m for m in _TOKEN.finditer(item) if not m.group().isspace()]
    if len(tokens) < 2:
        return None
    name = tokens[0].group()
    depth = 0
    end = len(item)
    for token in tokens[1:]:
        value = token.group()
        if depth == 0 and _INLINE.match(item[token.start():]):
            end = token.start()
            break
        if value in ("(", "[", "<"):
            depth += 1
        elif value in (")", "]", ">"):
            depth = max(0, depth - 1)
    type_text = item[tokens[0].end():end].strip()
    # Preserve whitespace and quoted identifiers while normalizing type words.
    type_text = _TOKEN.sub(lambda m: m.group() if m.group().startswith(("'", '"', "`")) else m.group().lower(), type_text)
    return DdlColumn(name, type_text, end != len(item))


def parse_ddl_table(lines: List[Line]) -> Optional[DdlTable]:
    # DATA nodes may contain whole lines; ordinary nodes contain individual tokens.
    source = "".join(n.token.prefix + n.token.token for line in lines for n in line.nodes)
    parts = _parts(source)
    if not parts:
        return None
    _, name, items, _ = parts
    columns: List[DdlColumn] = []
    constraints: List[DdlTableConstraint] = []
    for item in items:
        match = _CONSTRAINT.match(item)
        if match:
            constraints.append(DdlTableConstraint(" ".join(match.group().lower().split())))
        else:
            column = _column(item)
            if column:
                columns.append(column)
    return DdlTable(name, columns, constraints)


def _render(text: str) -> str:
    tokens = [m.group() for m in _TOKEN.finditer(text) if not m.group().isspace()]
    result = ""
    prev = ""
    for token in tokens:
        value = token if token.startswith(("'", '"', "`")) else token.lower()
        low = prev.lower()
        if not result:
            space = ""
        elif token in (",", ")", "]", ".", "::") or prev in ("(", "[", ".", "::", "<") or token == ">":
            space = ""
        elif token == "(":
            space = " " if low in ("check", "key", "unique", "in") else ""
        elif token == "<" and low in ("array", "struct", "map", "table"):
            space = ""
        else:
            space = " "
        result += space + value
        prev = token
    return result


def format_ddl(source: str, line_length: int) -> Optional[str]:
    parts = _parts(source)
    if not parts:
        return None
    header, _, items, suffix = parts
    # Leave unsupported variants, comments, templates, and multiple statements alone.
    if any(x in source for x in ("--", "/*", "{{", "{%", "#")):
        return None
    if not re.fullmatch(r"\s*(?:(?:partition\s+by|cluster\s+by|options)\b[\s\S]*)?;?\s*", suffix, re.I):
        return None
    if re.search(r";\s*\S", suffix):
        return None
    head = _render(header[:-1].strip()) + " ("
    result = [head]
    clean_items = [item for item in items if item]
    for i, item in enumerate(clean_items):
        result.append("    " + _render(item) + ("," if i + 1 < len(clean_items) else ""))
    result.append(")")
    suffix = suffix.strip()
    semi = suffix.endswith(";")
    if semi:
        suffix = suffix[:-1].strip()
    if suffix:
        clauses = re.split(r"(?i)\s+(?=(?:partition\s+by|cluster\s+by|options)\b)", suffix)
        for clause in clauses:
            rendered = _render(clause)
            if rendered.startswith("options("):
                rendered = "options" + rendered[len("options"):]
            result.append(rendered)
    if semi:
        result.append(";")
    return "\n".join(result) + "\n"
